import projects from "../data/projects.js";import blogs from "../data/blogs.js";const contactForm=document.querySelector(".form-js");const closeModal=document.querySelector(".close-modal");const contactModal=document.querySelector(".contact-modal");const tabButtons=document.querySelectorAll(".tab-button");const slider=document.querySelector(".slider");const sliderCont=document.querySelector(".skills-list");const projectListCont=document.querySelector(".project-list");const blogListCont=document.querySelector(".blog-list");document.querySelector(".copyright-date").innerText=new Date().getFullYear().toString();if(!projects?.length){document.querySelector(".projects-section").style.display="none"}
if(!blogs?.length){document.querySelector(".blog-section").style.display="none"}else{let allBlogs="";blogs.forEach((blog)=>{let blogPost=`
              <article class="blog fade-in" data-animationtype="animate">
                  <a href="${blog.link}"><h4 class="blog-title">${blog.title}.</h4></a>
                  <p class="blog-date">${blog.date}</p>
                  <p class="blog-content-preview">${blog.description}</p>
                  <a href="${blog.link}" class="button">Read More..</a>
              </article>
          
          `;allBlogs+=blogPost});blogListCont.innerHTML=allBlogs}
contactForm.addEventListener("submit",(event)=>{event.preventDefault();let data=new FormData(event.target);fetch(event.target.action,{method:"POST",headers:{Accept:"application/json",},body:data,}).then((response)=>{if(response.ok){contactModal.querySelector("h4").innerText="Message sent!";contactModal.querySelector("p").innerText="Thank you for reaching out! I'll get back to you shortly.";contactModal.style.display="block";contactModal.setAttribute("aria-hidden","false")}else{contactModal.querySelector("h4").innerText="Message failed to send!";contactModal.querySelector("p").innerText="It seems like there was a problem with the server. Please try again later.";contactModal.style.display="block"}
contactForm.reset()}).catch((error)=>{console.error("Network error:",error)})});closeModal.addEventListener("click",function(){contactModal.style.display="none";contactModal.setAttribute("aria-hidden","true")});tabButtons.forEach((tab)=>{tab.addEventListener("click",function(){tabButtons.forEach((tab)=>{tab.setAttribute("aria-selected","false");tab.classList.remove("active")});tab.classList.add("active");tab.setAttribute("aria-selected","true");const content=document.querySelector(`.${tab.dataset.tabname}`);content.parentNode.querySelectorAll(".tab-content").forEach((content)=>content.classList.remove("active"));content.classList.add("active")})});let threshold;if(window.innerWidth<=768){threshold=0.3}else{threshold=0.4}
let observer=new IntersectionObserver((entries)=>{entries.forEach((entry)=>{if(entry.isIntersecting){document.querySelectorAll("nav a").forEach((link)=>{link.classList.remove("active")});document.querySelectorAll("nav a").forEach((link)=>{if(link.getAttribute("href")==="#"+entry.target.getAttribute("id")){link.classList.add("active")}})}})},{threshold},);document.querySelectorAll("section").forEach((section)=>observer.observe(section))